package com.bank.eos;

import org.apache.kafka.clients.producer.*;
import org.apache.kafka.clients.consumer.*;
import org.apache.kafka.common.*;
import org.apache.kafka.common.serialization.*;
import org.apache.kafka.common.errors.ProducerFencedException;
import java.time.Duration;
import java.util.*;
import java.util.logging.*;

public class ExactlyOnceSettlementDemo {
    private static final Logger log = Logger.getLogger(ExactlyOnceSettlementDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // ---- Transactional PRODUCER ----
        Properties pp = new Properties();
        pp.put(ProducerConfig.BOOTSTRAP_SERVERS_CONFIG, "broker1:9092");
        pp.put(ProducerConfig.KEY_SERIALIZER_CLASS_CONFIG, StringSerializer.class.getName());
        pp.put(ProducerConfig.VALUE_SERIALIZER_CLASS_CONFIG, StringSerializer.class.getName());
        pp.put(ProducerConfig.ACKS_CONFIG, "all");
        pp.put(ProducerConfig.ENABLE_IDEMPOTENCE_CONFIG, "true");
        // A STABLE transactional.id: the coordinator uses it to fence zombies.
        pp.put(ProducerConfig.TRANSACTIONAL_ID_CONFIG, "settlement-tx-1");

        // ---- read_committed CONSUMER ----
        Properties cp = new Properties();
        cp.put(ConsumerConfig.BOOTSTRAP_SERVERS_CONFIG, "broker1:9092");
        cp.put(ConsumerConfig.KEY_DESERIALIZER_CLASS_CONFIG, StringDeserializer.class.getName());
        cp.put(ConsumerConfig.VALUE_DESERIALIZER_CLASS_CONFIG, StringDeserializer.class.getName());
        cp.put(ConsumerConfig.GROUP_ID_CONFIG, "settlement-service");
        cp.put(ConsumerConfig.ENABLE_AUTO_COMMIT_CONFIG, "false");
        cp.put(ConsumerConfig.ISOLATION_LEVEL_CONFIG, "read_committed");
        cp.put(ConsumerConfig.AUTO_OFFSET_RESET_CONFIG, "earliest");

        try (Producer<String, String> producer = new KafkaProducer<>(pp);
             Consumer<String, String> consumer = new KafkaConsumer<>(cp)) {

            // initTransactions() registers with the coordinator and BUMPS the epoch,
            // fencing any older producer instance using the same transactional.id.
            producer.initTransactions();
            consumer.subscribe(List.of("transfer-requests"));

            while (true) {
                ConsumerRecords<String, String> records = consumer.poll(Duration.ofSeconds(1));
                if (records.isEmpty()) continue;

                try {
                    producer.beginTransaction();   // open a transaction

                    Map<TopicPartition, OffsetAndMetadata> offsets = new HashMap<>();
                    for (ConsumerRecord<String, String> rec : records) {
                        // process: compute settlement for Rajesh/Priya transfer
                        SettlementResult result = settle(rec.value());
                        producer.send(new ProducerRecord<>(
                            "settlement-results", rec.key(), result.toJson()));
                        // remember the offset to commit INSIDE the transaction
                        offsets.put(new TopicPartition(rec.topic(), rec.partition()),
                                    new OffsetAndMetadata(rec.offset() + 1));
                        log.info(() -> "Settled " + rec.key() + " offset " + rec.offset());
                    }

                    // Atomically commit output records AND input offsets together.
                    producer.sendOffsetsToTransaction(offsets, consumer.groupMetadata());
                    producer.commitTransaction();   // coordinator writes commit markers
                    log.info("Transaction committed (results + offsets atomically)");

                } catch (ProducerFencedException fenced) {
                    // A newer instance took over; this zombie must stop.
                    log.severe("Producer fenced — a newer instance owns the transactional.id");
                    break;
                } catch (Exception e) {
                    producer.abortTransaction();    // roll back: no results, no offsets
                    log.log(Level.SEVERE, "Transaction aborted", e);
                }
            }
        }
    }

    private static SettlementResult settle(String request) {
        // Parse "SAV2001:CUR3001:50000" style request and produce a result.
        return new SettlementResult(request, "SETTLED");
    }
}

